<script setup lang="ts">
import {confirmAction} from '../lib/dialog';
import {ref,watch,onMounted} from 'vue';import {api,statusName,displayTime} from '../lib/api';
interface Row{id:string;public_number:string;title:string;status:string;version:number;event_name:string;delivered:number;updated_at:string}
const deleting=ref('');
const rows=ref<Row[]>([]),total=ref(0),page=ref(1),status=ref(''),busy=ref(false),error=ref('');let sequence=0;
async function load(){const seq=++sequence;busy.value=true;error.value='';try{const result=await api<{items:Row[];total:number}>('/api/submissions?'+new URLSearchParams({page:String(page.value),status:status.value}));if(seq===sequence){rows.value=result.items;total.value=result.total;}}catch(e){if(seq===sequence)error.value=(e as Error).message;}finally{if(seq===sequence)busy.value=false;}}
watch(status,()=>{page.value=1;void load();});watch(page,()=>void load());onMounted(load);
async function remove(row:Row){if(deleting.value||!await confirmAction(`删除「${row.title||'未命名草稿'}」？删除后无法继续填写，已上传的文件也会被清理。`))return;deleting.value=row.id;error.value='';try{await api('/api/submissions/'+row.id,{expectedVersion:row.version,operation_id:crypto.randomUUID()},'DELETE');if(rows.value.length===1&&page.value>1)page.value--;else await load();}catch(e){error.value=(e as Error).message;}finally{deleting.value='';}}
</script>
<template><div class="page"><header class="page-head"><h1>我的投稿</h1><RouterLink class="button primary" to="/submit/new">新建投稿</RouterLink></header><FieldLabel>投稿状态<select v-model="status"><option value="">全部状态</option><option value="draft">草稿</option><option value="pending">待审核</option><option value="rejected">已驳回</option><option value="approved">已通过</option></select></FieldLabel><p v-if="error" role="alert" class="alert error">{{ error }}</p><p v-if="busy" role="status">正在读取投稿…</p><section v-for="row in rows" :key="row.id" class="paper"><div class="inline"><h2 class="grow"><RouterLink :to="'/submit/'+row.id">{{ row.title||'未命名草稿' }}</RouterLink></h2><span class="badge" :class="row.status">{{ statusName(row.status) }}</span></div><p class="hint">{{ row.event_name }} · {{ row.public_number }}<br>{{ row.delivered?'作品已交付':'视频待交付' }}<br>最近更新：{{ displayTime(row.updated_at) }}</p><RouterLink class="button" :to="'/submit/'+row.id">{{ ['draft','rejected'].includes(row.status)?'继续填写':!row.delivered?'补交视频':'查看投稿' }}</RouterLink><button v-if="row.status==='draft'" class="danger delete-draft" :disabled="!!deleting||busy" @click="remove(row)">{{ deleting===row.id?'正在删除…':'删除草稿' }}</button></section><p v-if="!busy&&!rows.length" class="empty">{{ status?'没有此状态的投稿。':'还没有投稿，可点击“新建投稿”开始填写。' }}</p><div class="pagination"><button :disabled="busy||page===1" @click="page--">上一页</button><span>第 {{ page }} 页 · 共 {{ total }} 份</span><button :disabled="busy||page*20>=total" @click="page++">下一页</button></div></div></template>
<style scoped>.delete-draft{margin-left:12px}</style>
